package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextUniversalFrozenConstraints.*;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextWitnessResultTransport.*;

/** Negative units are real sourced products, not a success/coverage flag or borrowed private knowledge. */
public final class ContextUniversalSignedProductsRunner {
    static final int WORK=64000000;static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified,r.reason);return r;}
    static Result signed(Snapshot x,Snapshot a,Packet common,PrivatePool pool,int depth){Result r=ContextUniversalFrozenConstraints.closeSigned(rows(x,a),common,pool,16,depth,512,256,WORK);require(r.closed&&r.signedUnits,r.reason);ContextUniversalFrozenConstraints.check(r,depth,()->{});Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:r.proofs)audit(p,r,seen);return r;}
    static void audit(Proof p,Result r,Set<Proof> seen){if(!seen.add(p))return;if(p.original!=null){require(r.input.rows.contains(p.original)&&p.original.parts.contains(p.part),"actual native signed root");require(p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"whole original Source0");}else if(p.input!=null){require(r.local.items.stream().anyMatch(i->i==p.input)&&p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual carried input proof, no label-only binding");}else{audit(p.unit,r,seen);audit(p.horn,r,seen);org.kanger.ContextUniversalInputResiduals.Residual expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"actual signed principal resolvent");Set<Source> sources=new HashSet<>(p.unit.support.sources);sources.addAll(p.horn.support.sources);require(p.support.sources.equals(sources)&&p.support.depth==Math.max(p.unit.support.depth,p.horn.support.depth)+1,"complete signed parent Sources and depth");}}
    static boolean has(Packet p,String name,boolean positive){return p.items.stream().anyMatch(i->i.atom.predicate.equals(name)&&i.atom.positive==positive);}
    static Proof unit(Result r,String name,boolean positive){return r.proofs.stream().filter(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals(name)&&p.clause.literals.get(0).positive==positive).findFirst().get();}
    static ConstraintTransfer transfer(Result r,Packet p,PrivatePool pool,int depth){ConstraintTransfer t=pool==null?ContextWitnessResultTransport.transferConstraints(r,p,depth,WORK):ContextWitnessResultTransport.transferConstraintsPrivate(r,pool,depth,WORK);require(t.transferred,t.reason);require(t.proof==r&&t.before==p&&t.privateBefore==pool,"exact owning signed proof/frame retained");ContextUniversalFrozenBranchRunner.unmarked(t.output);return t;}
    static void no(ConstraintTransfer t,String why){require(!t.transferred&&t.output==null&&t.local==null&&t.privateAfter==null,why+": "+t.reason);}
    static void originalExample()throws Exception {
        String rule="!@w left(w,1)&&right(w,1)->p(w,1);",right="!right(1,1);",negative="!~p(1,1);",left="!left(1,1);";
        Snapshot x=bind(true,"!anchor(1); "+rule),a=bind(false,left+"!p(1,1);"),b=bind(false,right+negative);Packet common=ContextPrivateWitnessPoolRunner.common(x);
        Result beforeA=signed(x,a,common,null,16),beforeB=signed(x,b,common,null,16);require(!beforeA.xRefuted&&!beforeB.xRefuted,"both independent cuts compatible before new common production");
        Proof negLeft=unit(beforeB,"left",false);Set<Source> expected=new HashSet<>(Arrays.asList(ContextPrivateWitnessPoolRunner.source(x,rule),ContextPrivateWitnessPoolRunner.source(b,right),ContextPrivateWitnessPoolRunner.source(b,negative)));
        require(negLeft.support.sources.equals(expected)&&negLeft.support.depth==2,"original counterexample produces negative left2 with all three actual Sources");require(beforeB.proofs.stream().anyMatch(p->p.unit!=null&&!p.unit.clause.literals.get(0).positive),"a checked negative unit is an actual inference parent");
        ConstraintTransfer proposed=transfer(beforeB,common,null,2);require(has(proposed.output,"left",false)&&!has(proposed.output,"right",true)&&!has(proposed.output,"p",false),"X-dependent negative production shared, raw foreign facts remain absent");
        require(!signed(x,a,common,null,16).xRefuted,"A with same immutable old input still cannot see B's same-round production");
        Result afterA=signed(x,a,proposed.output,null,16);require(afterA.xRefuted,"next A qualification rejects candidate rule after B negative production");expected.add(ContextPrivateWitnessPoolRunner.source(a,left));require(afterA.emptyProofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.equals(expected)),"collision3 retains B history and actual A left, excludes unrelated A p and X anchor");
        no(ContextWitnessResultTransport.transferConstraints(afterA,proposed.output,16,WORK),"refuted cut cannot publish any products");
        no(ContextWitnessResultTransport.transferConstraints(beforeB,common,1,WORK),"negative product depth limit no prefix");
        no(ContextWitnessResultTransport.transferConstraints(beforeB,ContextPrivateWitnessPoolRunner.common(x),16,WORK),"equal common contents cannot replace actual input object");
        no(ContextWitnessResultTransport.transferConstraints(beforeB,common,16,1),"transfer work cap no prefix");
        Result legacy=ContextUniversalFrozenConstraints.close(rows(x,b),common,null,16,16,512,256,WORK);require(legacy.closed&&!legacy.signedUnits&&legacy.proofs.stream().noneMatch(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("left")&&!p.clause.literals.get(0).positive),"legacy positive-unit projection retains explicit old scope");no(ContextWitnessResultTransport.transferConstraints(legacy,common,16,WORK),"positive-only closed receipt cannot masquerade as signed closure");
        Map<Cut,Packet> alleged=Collections.singletonMap(Cut.of(b),proposed.output);require(ContextWitnessResultTransport.family(common,Collections.singletonList(Cut.of(b)),WORK).finish(alleged,WORK).status==FamilyStatus.INCOMPLETE,"signed products still have no family STEP");
        require(!has(common,"left",false)&&common.items.size()==1,"initial common untouched by proposal and refusal");
    }
    static void originsAndPrivate()throws Exception {
        String seed="!$w p(w,1);",rule="!@w p(w,1)->q(w,1);",negative="!@w ~q(w,1);";
        Snapshot x=bind(true,seed),a=bind(false,rule+negative);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result refuted=signed(x,a,common,null,16);require(refuted.xRefuted,"negative unit propagation preserves actual carried rigid binder");
        Proof np=unit(refuted,"p",false);require(np.clause.variables.size()==1,"native universal contrapositive remains symbolic, no finite-value sample");
        Snapshot anchor=bind(true,"!anchor(1);"),privateFacts=bind(false,"!$w seed(w,1);"),neg=bind(false,"!@w seed(w,1)->~flag(w,1);");Snapshot target=ContextProductionNativeBinding.trusted("own",Arrays.asList(privateFacts,neg),WORK);Packet base=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool pool=ContextWitnessResultTransport.privatePool(base,anchor,target,WORK);Result local=signed(anchor,target,base,pool,16);ConstraintTransfer out=transfer(local,base,pool,16);
        require(has(out.local,"flag",false)&&!has(out.output,"flag",false)&&!has(out.output,"seed",true),"negative private unit stays local without unrelated X anchor");require(out.privateAfter.common==base&&out.privateAfter.local==out.local&&!has(pool.local,"flag",false),"new immutable private continuation retains signed units without mutating old state");
        no(ContextWitnessResultTransport.transferConstraints(local,base,16,WORK),"private signed receipt cannot use common-only transfer");
        Snapshot owner=bind(true,"!anchor(1); !@w seed(w,1)->~flag(w,1);");Packet owned=ContextPrivateWitnessPoolRunner.common(owner);PrivatePool actual=ContextWitnessResultTransport.privatePool(owned,owner,privateFacts,WORK);ConstraintTransfer shared=transfer(signed(owner,privateFacts,owned,actual,16),owned,actual,16);require(has(shared.output,"flag",false)&&!has(shared.output,"seed",true),"actual X-owned rule can share derived negative fact while raw private seed stays local");
        Item flag=shared.output.items.stream().filter(i->i.atom.predicate.equals("flag")&&!i.atom.positive).findFirst().get();require(flag.atom.arguments.get(0).origin.source.equals(privateFacts.primary.get(0).source)&&flag.proofs.stream().allMatch(p->p.depth==1&&p.sources.size()==2),"negative witness fact retains physical Source/binder and exact grade");
        Snapshot independent=bind(false,"!$w p(w,1); !$w q(w,1);");Snapshot checkX=bind(true,"!anchor(1); !@w p(w,1)->~q(w,1);");Packet input=ContextPrivateWitnessPoolRunner.common(checkX);PrivatePool split=ContextWitnessResultTransport.privatePool(input,checkX,independent,WORK);Result separate=signed(checkX,independent,input,split,16);require(!separate.xRefuted,"negative conclusions cannot collapse distinct witness Origins");
    }
    static void balancedAndBounds()throws Exception {
        Snapshot x=bind(true,"!p(1);"),a=bind(false,"!@w p(w)->q(w);"),b=bind(false,"!@w q(w)->r(w);"),c=bind(false,"!~r(1);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b,c),WORK);Packet common=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalNativeRows.Result inventory=rows(x,group);
        Result positive=ContextUniversalFrozenConstraints.close(inventory,common,null,16,3,512,256,WORK),both=signed(x,group,common,null,2);require(positive.closed&&positive.emptyProofs.stream().allMatch(p->p.support.depth==3)&&both.emptyProofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==4),"signed resolution finds balanced empty2 without resetting positive-only empty3");no(ContextWitnessResultTransport.transferConstraints(both,common,16,WORK),"balanced refutation never exports explosive products");
        Snapshot anchor=bind(true,"!anchor(1);"),p=bind(false,"!p(1);"),np=bind(false,"!~p(1);");Snapshot invalid=ContextProductionNativeBinding.trusted("own",Arrays.asList(p,np),WORK);Packet input=ContextPrivateWitnessPoolRunner.common(anchor);Result foreign=signed(anchor,invalid,input,null,16);require(foreign.foreignRefuted&&!foreign.xRefuted,"foreign-only invalid cut retains actual provenance");no(ContextWitnessResultTransport.transferConstraints(foreign,input,16,WORK),"private-only refuted cut also cannot publish");
        Result limited=ContextUniversalFrozenConstraints.closeSigned(inventory,common,null,1,16,512,256,WORK);require(!limited.closed&&limited.proofs.isEmpty()&&limited.emptyProofs.isEmpty(),"signed round cap hides partial proof state");no(ContextWitnessResultTransport.transferConstraints(limited,common,16,WORK),"failed signed receipt cannot publish");
        no(ContextWitnessResultTransport.transferConstraints(null,common,16,WORK),"actual sealed signed proof required");
        Result wrong=ContextUniversalFrozenConstraints.closeSigned(rows(anchor,ContextPrivateWitnessPoolRunner.bind(false,"!$w extra(w);")),input,null,16,16,512,256,WORK);require(!wrong.closed&&wrong.proofs.isEmpty(),"missing whole private witness input remains atomic in signed mode");
    }
    static void alternativesAndSymbolic()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w left(w,1)&&right(w,1)->p(w,1);"),b=bind(false,"!right(1,1); !~p(1,1);"),loop=bind(false,"!@w left(w,1)->left(w,1);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(b,loop),WORK);Packet input=ContextPrivateWitnessPoolRunner.common(x);Result r=signed(x,group,input,null,16);ConstraintTransfer t=transfer(r,input,null,3);
        Item left=t.output.items.stream().filter(i->i.atom.predicate.equals("left")&&!i.atom.positive).findFirst().get();require(left.proofs.stream().anyMatch(p->p.sources.size()==3&&p.depth==2)&&left.proofs.stream().anyMatch(p->p.sources.size()==4&&p.depth==3),"fixed negative products retain deeper Source supersets and genuine minima");
        no(ContextWitnessResultTransport.transferConstraints(r,input,2,WORK),"shorter other-Source product cannot hide deeper exact Source obligation");
        Snapshot reverse=ContextProductionNativeBinding.trusted("own",Arrays.asList(loop,b),WORK);ConstraintTransfer back=transfer(signed(x,reverse,input,null,16),input,null,3);require(ContextWitnessResultTransport.sameContents(t.output,back.output,WORK),"trusted member order preserves all fixed signed products and grades");
        Snapshot generic=bind(true,"!anchor(1); !@w ~p(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(generic);Result universal=signed(generic,null,common,null,16);ConstraintTransfer symbolic=transfer(universal,common,null,16);require(!has(symbolic.output,"p",false)&&!symbolic.commonChanged,"free-variable negative units stay symbolic, no finite-value sampling or completeness claim");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-products-").toString());originalExample();originsAndPrivate();balancedAndBounds();alternativesAndSymbolic();System.out.println("CONTEXT_UNIVERSAL_SIGNED_PRODUCTS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
